/* Généré depuis assets/fonts/*.ttf (Inter 4.1, SIL Open Font License, sous-ensemble latin). Ne pas modifier à la main.
 * Pourquoi du base64 : Wrangler n'importe pas les .ttf sans règle « Data » dans wrangler.jsonc (socle) ; ce module marche partout
 * (bundler, Vitest, tsc). Régénérer : voir REGLES.md, section « Polices ». */
export const INTER_REGULAR_B64 = "";
export const INTER_SEMIBOLD_B64 = "";
export function b64ToBytes(b64: string): Uint8Array {
  const s = atob(b64); const u = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i);
  return u;
}
let cache: { regular: Uint8Array; semibold: Uint8Array } | null = null;
export function interFonts() {
  return (cache ||= { regular: b64ToBytes(INTER_REGULAR_B64), semibold: b64ToBytes(INTER_SEMIBOLD_B64) });
}
